"use strict";(self.webpackChunkenterprise_ai_agents_applied_ml_book=self.webpackChunkenterprise_ai_agents_applied_ml_book||[]).push([[7959],{8692(e,t,n){n.r(t),n.d(t,{assets:()=>c,contentTitle:()=>d,default:()=>g,frontMatter:()=>l,metadata:()=>i,toc:()=>p});const i=JSON.parse('{"id":"part1-enterprise-ai-delivery/seven-days-after-kickoff","title":"AI Lead Playbook: Seven Days After Kickoff (Document Q&A Pilot)","description":"This tutorial is a step-by-step guide for what an AI Lead Engineer does immediately after the pilot kickoff meeting. It is aligned to our example project: Executive Document Q&A (meeting notes/packs \u2192 cited answers) w...","source":"@site/docs/part1-enterprise-ai-delivery/05-seven-days-after-kickoff.mdx","sourceDirName":"part1-enterprise-ai-delivery","slug":"/part1-enterprise-ai-delivery/05-seven-days-after-kickoff","permalink":"/tutorials/part1-enterprise-ai-delivery/05-seven-days-after-kickoff","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785375762000,"sidebarPosition":5,"frontMatter":{"title":"AI Lead Playbook: Seven Days After Kickoff (Document Q&A Pilot)","slug":"/part1-enterprise-ai-delivery/05-seven-days-after-kickoff","description":"This tutorial is a step-by-step guide for what an AI Lead Engineer does immediately after the pilot kickoff meeting. It is aligned to our example project: Executive Document Q&A (meeting notes/packs \u2192 cited answers) w...","sidebar_label":"5. Seven days after kickoff","pagination_label":"5. Seven days after kickoff","hide_title":true,"hide_table_of_contents":true},"sidebar":"bookSidebar","previous":{"title":"4. Pilot kickoff meeting","permalink":"/tutorials/part1-enterprise-ai-delivery/04-kickoff-meeting"},"next":{"title":"6. Architecture reference design","permalink":"/tutorials/part1-enterprise-ai-delivery/06-architecture-reference-design"}}');var s=n(4848),o=n(8453),a=n(8172);const r=JSON.parse('{"sourcePath":"part1-enterprise-ai-delivery/05-seven-days-after-kickoff.html","route":"/part1-enterprise-ai-delivery/05-seven-days-after-kickoff","kind":"chapter","partId":"part1","partLabel":"Part I - Enterprise AI Delivery Lifecycle","accent":"blue","heading":"AI Lead Playbook: 7 Days After Kickoff","title":"AI Lead Playbook: Seven Days After Kickoff (Document Q&A Pilot)","description":"This tutorial is a step-by-step guide for what an AI Lead Engineer does immediately after the pilot kickoff meeting. It is aligned to our example project: Executive Document Q&A (meeting notes/packs \u2192 cited answers) w...","readingMinutes":6,"bodyClass":"","normalizeMath":false,"toc":[{"id":"northstar","label":"0) North Star: what we\u2019re actually building"},{"id":"week","label":"1) The 7 days after kickoff (what I do, day by day)"},{"id":"docs","label":"2) The AI Lead Document Pack (aligned to this project)"},{"id":"roles","label":"3) Who writes what (team of 5)"},{"id":"gates","label":"4) Release gates (what must be true before pilot users get access)"},{"id":"checklist","label":"5) AI Lead checklist (copy/paste)"}],"html":"<div class=\\"container\\">\\n    \\n    <p class=\\"lead\\">\\n      This tutorial is a step-by-step guide for what an <strong>AI Lead Engineer</strong> does immediately after the pilot kickoff meeting.\\n      It is aligned to our example project: <strong>Executive Document Q&amp;A</strong> (meeting notes/packs \u2192 cited answers) with strict access control.\\n      The focus is not \u201cbuild a demo\u201d \u2014 it\u2019s \u201cship a safe, measurable pilot.\u201d\\n    </p>\\n\\n    <div class=\\"meta\\">\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Project</div>\\n        Executive Document Q&amp;A (Cited RAG Assistant)\\n      </div>\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Enterprise reality</div>\\n        Governance + access + evaluation gates must exist before users see it\\n      </div>\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">AI Lead outcome</div>\\n        Convert kickoff decisions into approvals + backlog + evaluation + operating model\\n      </div>\\n      <div class=\\"box\\">\\n        <div class=\\"k\\">Team shape (example)</div>\\n        5 engineers (data + software) + stakeholders (EA/Ops/Security/Data Owners)\\n      </div>\\n    </div>\\n\\n    <ul class=\\"toc\\">\\n      <li><a href=\\"#northstar\\">North Star (what we\u2019re building)</a></li>\\n      <li><a href=\\"#week\\">7-day plan</a></li>\\n      <li><a href=\\"#docs\\">Document pack (templates)</a></li>\\n      <li><a href=\\"#roles\\">Who writes what</a></li>\\n      <li><a href=\\"#gates\\">Release gates</a></li>\\n      <li><a href=\\"#checklist\\">AI lead checklist</a></li>\\n    </ul>\\n\\n    <h2 id=\\"northstar\\">0) North Star: what we\u2019re actually building</h2>\\n    <div class=\\"card\\">\\n      <p>\\n        A pilot tool that answers questions like: <em>\u201cWhat did Chandima mention about no meeting on 1 Dec?\u201d</em>\\n        and returns:\\n      </p>\\n      <ul>\\n        <li><strong>Short answer</strong> (2\u20136 sentences)</li>\\n        <li><strong>Citations</strong> (doc title + link + excerpt; timestamp if transcript exists)</li>\\n        <li><strong>Safe failure</strong> (\u201cnot found\u201d when evidence is insufficient)</li>\\n        <li><strong>Audit trail</strong> (who asked, what evidence was used)</li>\\n      </ul>\\n\\n      <div class=\\"ok\\">\\n        <strong>Lead-level framing:</strong> \u201cIf you can\u2019t cite it, you can\u2019t say it.\u201d\\n      </div>\\n\\n      <div class=\\"warn\\">\\n        <strong>Pilot constraint:</strong> we only answer over an approved, bounded corpus. \u201cAll company docs\u201d is a later phase.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"week\\">1) The 7 days after kickoff (what I do, day by day)</h2>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"day-0-1-freeze-decisions-unblock-access\\">Day 0\u20131: Freeze decisions + unblock access</h3>\\n      <p><span class=\\"pill\\">Goal</span> Make the pilot buildable by eliminating ambiguity and starting approval workflows.</p>\\n      <ol>\\n        <li><strong>Publish the Decision Record</strong> (pilot cohort, corpus, exclusions, success metrics, named owners).</li>\\n        <li><strong>Create the Approvals Tracker</strong> (data owner approvals, IAM/service identity requests, privacy/risk checks).</li>\\n        <li><strong>Confirm the pilot cohort mechanism</strong>: names vs org group (recommended: group).</li>\\n      </ol>\\n\\n      <div class=\\"callout\\">\\n        <strong>Why this is first:</strong> approvals take longer than engineering. Start them immediately or delivery stalls in week 2.\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"day-2-3-produce-reviewable-design-sprint-ready-execution-plan\\">Day 2\u20133: Produce reviewable design + sprint-ready execution plan</h3>\\n      <p><span class=\\"pill\\">Goal</span> Get \u201capproval to build\u201d and start engineering with a clear vertical slice milestone.</p>\\n      <ol>\\n        <li><strong>Write the Architecture Review Pack (HLD)</strong> with trust boundaries, access model, data flows, risks.</li>\\n        <li><strong>Write 3\u20135 ADRs</strong> documenting key decisions (citations-only, tenant isolation, corpus gating, etc.).</li>\\n        <li><strong>Convert the plan into epics + stories</strong> and define the <em>vertical slice</em> milestone.</li>\\n      </ol>\\n\\n      <div class=\\"ok\\">\\n        <strong>Vertical slice definition:</strong> ingest a small approved sample \u2192 retrieve with filters \u2192 answer with citations \u2192 audit log \u2192 eval run.\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"day-3-4-co-design-with-ea-ops-and-build-the-golden-set\\">Day 3\u20134: Co-design with EA + Ops and build the \u201cGolden Set\u201d</h3>\\n      <p><span class=\\"pill\\">Goal</span> Lock real workflow and create evaluation gates.</p>\\n      <ol>\\n        <li><strong>Run a co-design session</strong> with EA + Ops to define what \u201cusable output\u201d looks like.</li>\\n        <li><strong>Collect 30\u201350 real questions</strong> and record expected source documents.</li>\\n        <li><strong>Define the scoring rubric</strong> (citation correctness, groundedness, refusal correctness).</li>\\n      </ol>\\n\\n      <div class=\\"callout\\">\\n        <strong>AI lead rule:</strong> you don\u2019t \u201cfinish prompting\u201d \u2014 you ship prompts behind eval gates and iterate with evidence.\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"day-5-7-set-the-operating-model-drive-the-first-slice-to-demo-readiness\\">Day 5\u20137: Set the operating model + drive the first slice to demo readiness</h3>\\n      <p><span class=\\"pill\\">Goal</span> Make the pilot safe to run, not just build.</p>\\n      <ol>\\n        <li><strong>Define runbooks</strong> (wrong answer investigation, \u201cnot found\u201d investigation, dependency outage behavior).</li>\\n        <li><strong>Define go-live checklist</strong> (auth, gating, audit logs, eval threshold, dashboards).</li>\\n        <li><strong>Demo the vertical slice internally</strong> to stakeholders and capture feedback.</li>\\n      </ol>\\n\\n      <div class=\\"warn\\">\\n        <strong>Important:</strong> A pilot without monitoring, audit logs, and a support owner is a \u201cprototype,\u201d not enterprise delivery.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"docs\\">2) The AI Lead Document Pack (aligned to this project)</h2>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"2-1-decision-record-template\\">2.1 Decision Record (template)</h3>\\n      <p class=\\"small\\">This is the single most important artifact to prevent scope drift.</p>\\n      <pre>Title: Exec Doc Q&amp;A Pilot \u2014 Decision Record (v1)\\n\\n1) Pilot Cohort\\n- Access group: docqa-pilot-execs@company.com\\n- Access group: docqa-pilot-eas@company.com\\n- Pilot champion: (name)\\n\\n2) Approved Corpus\\n- Source: (Drive/SharePoint/etc.)\\n- Locations: (folder IDs / site URLs)\\n- Time window: last 6 months\\n- Exclusions: HR, Legal, customer PII-heavy corpora\\n\\n3) Success Metrics (Pilot)\\n- EA time saved: baseline measured week 0 \u2192 target +30% improvement\\n- Citation correctness: &gt;= X on golden set\\n- Adoption: weekly active users &gt;= Y\\n\\n4) Go-live Gate (Pilot)\\n- All access controls enforced\\n- Audit logging active\\n- Golden set passes thresholds\\n- Monitoring dashboards live\\n- Named support owner\\n\\n5) Owners / Contacts\\n- Business owner:\\n- Data owner:\\n- Security/IAM:\\n- Privacy/Risk:\\n- AI lead:\\n      </pre>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"2-2-architecture-review-pack-hld-what-it-must-contain\\">2.2 Architecture Review Pack (HLD) \u2014 what it must contain</h3>\\n      <ul>\\n        <li><strong>System diagram + trust boundaries</strong> (where identity is verified, where data is stored, where LLM is called)</li>\\n        <li><strong>Identity + access model</strong>: SSO, group gating, corpus gating, tenant/user mapping</li>\\n        <li><strong>Data flow</strong>: what is ingested, stored, indexed, retrieved, and sent to the LLM</li>\\n        <li><strong>Threats &amp; mitigations</strong>: leakage, prompt injection, sensitive logs, exfil</li>\\n        <li><strong>Operational view</strong>: metrics/logs/traces, failure modes, runbook ownership</li>\\n      </ul>\\n      <div class=\\"callout\\">\\n        <strong>Architecture review purpose:</strong> approval to build (early) and approval to go-live (later).\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"2-3-adrs-architecture-decision-records-for-this-project\\">2.3 ADRs (Architecture Decision Records) for this project</h3>\\n      <ul>\\n        <li><code>ADR-001</code> \u2014 \u201cCited answers only; refuse without evidence.\u201d</li>\\n        <li><code>ADR-002</code> \u2014 \u201cTenant isolation strategy (tenant_id/user_id; DB backstop).\u201d</li>\\n        <li><code>ADR-003</code> \u2014 \u201cPilot uses corpus allowlist; per-doc ACLs in phase 2.\u201d</li>\\n        <li><code>ADR-004</code> \u2014 \u201cModel boundary: send only retrieved snippets; redact sensitive patterns.\u201d</li>\\n        <li><code>ADR-005</code> \u2014 \u201cEvaluation gates required for prompt/retrieval changes.\u201d</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"2-4-ea-ops-co-design-notes-output-contract\\">2.4 EA/Ops Co-Design Notes + Output Contract</h3>\\n      <ul>\\n        <li>What counts as \u201cproof\u201d: snippet + link, optional timestamp</li>\\n        <li>Answer length and tone suitable for executive briefings</li>\\n        <li>Refusal rules (\u201cnot found\u201d behavior)</li>\\n        <li>Examples of good questions vs bad questions</li>\\n      </ul>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"2-5-golden-set-rubric-evaluation-pack\\">2.5 Golden Set + Rubric (evaluation pack)</h3>\\n      <p class=\\"small\\">You build this from real EA/Ops questions. It becomes your go-live gate.</p>\\n      <pre>Golden Set entry example:\\n- Question: \\"What did Chandima mention about no meeting on 1 Dec?\\"\\n- Expected evidence: \\"Exec Forum Minutes 2024-12-01\\" section \\"Agenda changes\\"\\n- Score:\\n  - Citation correctness (0/1/2)\\n  - Groundedness (0/1/2)\\n  - Refusal correctness (0/1)\\n  - Helpfulness (0/1)\\n      </pre>\\n      <div class=\\"ok\\">\\n        <strong>Lead-level move:</strong> every prompt/retrieval change runs the golden set and compares metrics.\\n      </div>\\n    </div>\\n\\n    <div class=\\"card\\">\\n      <h3 id=\\"2-6-runbooks-go-live-checklist\\">2.6 Runbooks + Go-live checklist</h3>\\n      <ul>\\n        <li><strong>Runbook:</strong> \u201cWrong answer\u201d \u2192 check citations \u2192 check retrieved chunks \u2192 check ingestion freshness</li>\\n        <li><strong>Runbook:</strong> \u201cNot found\u201d \u2192 verify corpus boundaries \u2192 verify metadata \u2192 verify index update</li>\\n        <li><strong>Checklist:</strong> access control enforced, audit logs written, eval thresholds met, dashboards live</li>\\n      </ul>\\n    </div>\\n\\n    <h2 id=\\"roles\\">3) Who writes what (team of 5)</h2>\\n    <div class=\\"card\\">\\n      <table>\\n        <thead>\\n          <tr>\\n            <th>Artifact / Workstream</th>\\n            <th>Primary owner</th>\\n            <th>Support</th>\\n          </tr>\\n        </thead>\\n        <tbody>\\n          <tr>\\n            <td>Decision record, ADRs, eval gates</td>\\n            <td><strong>AI Lead</strong></td>\\n            <td>Business owner, EM</td>\\n          </tr>\\n          <tr>\\n            <td>Architecture review pack</td>\\n            <td><strong>AI Lead</strong></td>\\n            <td>Security/IAM, EM, senior engineer</td>\\n          </tr>\\n          <tr>\\n            <td>Golden set + rubric</td>\\n            <td><strong>AI Lead</strong></td>\\n            <td>EA rep, Ops rep, SME</td>\\n          </tr>\\n          <tr>\\n            <td>Ingestion &amp; metadata</td>\\n            <td>Data engineers (2)</td>\\n            <td>AI lead (schema), data owners</td>\\n          </tr>\\n          <tr>\\n            <td>Backend/auth/audit</td>\\n            <td>Software engineers (2)</td>\\n            <td>Security/IAM, AI lead (requirements)</td>\\n          </tr>\\n          <tr>\\n            <td>Runbooks + dashboards</td>\\n            <td>EM / senior engineer</td>\\n            <td>AI lead (what to measure), Ops</td>\\n          </tr>\\n        </tbody>\\n      </table>\\n    </div>\\n\\n    <h2 id=\\"gates\\">4) Release gates (what must be true before pilot users get access)</h2>\\n    <div class=\\"card\\">\\n      <ul>\\n        <li><strong>Auth gate:</strong> only allowed org group can access</li>\\n        <li><strong>Corpus gate:</strong> retrieval restricted to approved doc sets</li>\\n        <li><strong>Citation gate:</strong> answers contain citations or refuse</li>\\n        <li><strong>Leakage gate:</strong> cross-user/cross-corpus tests pass</li>\\n        <li><strong>Audit gate:</strong> every answer logs user + cited sources</li>\\n        <li><strong>Eval gate:</strong> golden set meets threshold</li>\\n        <li><strong>Ops gate:</strong> dashboards + runbook + support owner exist</li>\\n      </ul>\\n\\n      <div class=\\"warn\\">\\n        <strong>Enterprise truth:</strong> \u201cWorking\u201d is not enough. It must be <em>measurable, auditable, and operable</em>.\\n      </div>\\n    </div>\\n\\n    <h2 id=\\"checklist\\">5) AI Lead checklist (copy/paste)</h2>\\n    <div class=\\"card\\">\\n      <ul>\\n        <li>\u2610 Decision record published and agreed</li>\\n        <li>\u2610 Approvals tracker created with named owners</li>\\n        <li>\u2610 Architecture review pack drafted and review booked</li>\\n        <li>\u2610 ADRs created for key choices</li>\\n        <li>\u2610 EA/Ops co-design session completed</li>\\n        <li>\u2610 Golden set + rubric created</li>\\n        <li>\u2610 Sprint backlog created + vertical slice milestone defined</li>\\n        <li>\u2610 Runbooks drafted + go-live checklist defined</li>\\n        <li>\u2610 Pilot comms/training outline assigned to business owner/EA</li>\\n      </ul>\\n\\n      <div class=\\"ok\\">\\n        <strong>Result:</strong> by the end of week 1, you have a governable plan + measurable gates + build momentum.\\n      </div>\\n    </div>\\n\\n    <div class=\\"tr-note\\">\\n      <strong>Week-one evidence pack</strong>\\n      Produce a filled-out <strong>Decision Record</strong>, an\\n      <strong>Architecture Review Pack outline</strong>, and a 30-question\\n      <strong>Golden Set</strong> grounded in the meeting-notes scenario.\\n      Together they connect governance decisions to measurable model behavior.\\n    </div>\\n  </div>"}'),l={title:"AI Lead Playbook: Seven Days After Kickoff (Document Q&A Pilot)",slug:"/part1-enterprise-ai-delivery/05-seven-days-after-kickoff",description:"This tutorial is a step-by-step guide for what an AI Lead Engineer does immediately after the pilot kickoff meeting. It is aligned to our example project: Executive Document Q&A (meeting notes/packs \u2192 cited answers) w...",sidebar_label:"5. Seven days after kickoff",pagination_label:"5. Seven days after kickoff",hide_title:!0,hide_table_of_contents:!0},d=void 0,c={},p=[];function u(e){return(0,s.jsx)(a.A,{content:r})}function g(e={}){const{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(u,{...e})}):u()}}}]);